#!/usr/bin/env bash
#
# Applies initial-install-iplus.sql to a fresh iPlus database, exactly once.
#
# Runs inside the mssql-init container (mcr.microsoft.com/mssql/server) and is
# mounted from artifacts/release. The script is generated by gip.tool.dbscript
# (see docs/release-process.md) and contains schema + seed/master data.
#
# Idempotency:
#   - a marker file in the /state volume records that the script was applied
#   - the generated script itself guards every seed table with IF NOT EXISTS
#   - if the database already exists and has tables, the script is skipped
#
set -euo pipefail

SCRIPT="/scripts/initial-install-iplus.sql"
MARKER="/state/initial-install-iplus.applied"
DB_NAME="${IPLUS_DB_NAME:-iPlusV5}"
SQLCMD="/opt/mssql-tools18/bin/sqlcmd"

if [ ! -f "$SCRIPT" ]; then
	echo "ERROR: $SCRIPT not found."
	echo "Generate it with gip.tool.dbscript and place it in artifacts/release/."
	exit 1
fi

if [ -f "$MARKER" ]; then
	echo "initial-install-iplus.sql was already applied ($MARKER). Skipping."
	exit 0
fi

echo "Waiting for SQL Server to accept connections ..."
for attempt in $(seq 1 60); do
	if "$SQLCMD" -S sqlserver -U sa -P "$MSSQL_SA_PASSWORD" -C -Q "SELECT 1" -b -o /dev/null 2>/dev/null; then
		break
	fi
	if [ "$attempt" -eq 60 ]; then
		echo "ERROR: SQL Server did not become reachable."
		exit 1
	fi
	sleep 2
done

echo "Checking whether database '$DB_NAME' already exists ..."
EXISTS="$("$SQLCMD" -S sqlserver -U sa -P "$MSSQL_SA_PASSWORD" -C -h -1 -W \
	-Q "SET NOCOUNT ON; SELECT COUNT(*) FROM sys.databases WHERE name = N'$DB_NAME'" | tr -d '[:space:]')"

if [ "$EXISTS" != "0" ]; then
	echo "Database '$DB_NAME' already exists. Skipping the initial install script."
	echo "Existing installations only run the incremental DbScripts updates."
	touch "$MARKER"
	exit 0
fi

echo "Creating database '$DB_NAME' ..."
"$SQLCMD" -S sqlserver -U sa -P "$MSSQL_SA_PASSWORD" -C -b \
	-Q "CREATE DATABASE [$DB_NAME]"

echo "Applying initial-install-iplus.sql (this can take several minutes) ..."
"$SQLCMD" -S sqlserver -U sa -P "$MSSQL_SA_PASSWORD" -C -b -d "$DB_NAME" -i "$SCRIPT"

touch "$MARKER"
echo "Initial install completed."
